# ---- phase 2 lessons (c17-c22) ----
L.append(dict(id='c17-consistent-hashing',title='Consistent Hashing',used=['d02-hash-ring'],scenes=[
 S('title',['This lesson covers consistent hashing, the trick that lets caches and databases add servers without reshuffling everything.'],title='Consistent Hashing',sub='Seats around a round table'),
 S('analogy',['Picture a round table with servers sitting at a few seats.','Each key also gets a spot on the edge of the table, using a hash.','A key walks clockwise and belongs to the first server it meets.','If a new server sits down, only the keys just before its seat move to it. Everyone else stays put.'],text='Servers sit around a round table. Each key walks clockwise to the first server. A new server only takes keys from its one neighbour.',icons=['hash','ring','clockwise','few moves']),
 S('bullets',['First, why not just use hash of key modulo n?','With modulo, changing n from four servers to five changes the answer for about eighty percent of keys.','For a cache, that means almost every lookup misses at once, and the database behind it gets crushed.','Consistent hashing moves only about one over n of the keys.'],title='Why not hash % n?',items=['hash % 4 → hash % 5 moves ~80% of keys','Cache stampede on the database','Consistent hashing moves ~1/n','Used by Dynamo, Cassandra, memcached clients']),
 S('ring',['Here is the ring with three servers, A, B and C.','Key k one hashes to here, walks clockwise and lands on B.','Now server D joins between A and B.','Only key k one moves from B to D. Keys owned by A and C do not move at all.'],title='Keys walk clockwise',states=[dict(points=[['A',30],['B',150],['C',270]],note='3 servers on the ring'),dict(points=[['A',30],['B',150],['C',270]],keys=[['k1',100],['k2',200],['k3',330]],side={'k1':'B','k2':'C','k3':'A'}),dict(points=[['A',30],['D',80,'#a78bfa'],['B',150],['C',270]],keys=[['k1',100],['k2',200],['k3',330]],side={'k1':'B','k2':'C','k3':'A'},note='D joins'),dict(points=[['A',30],['D',80,'#a78bfa'],['B',150],['C',270]],keys=[['k1',100],['k2',200],['k3',330]],side={'k1':'B (k1 > 80)','k2':'C','k3':'A'},note='only keys in (30, 80] move to D')]),
 S('bullets',['Vocabulary.','Virtual nodes: each real server sits at many seats, like a hundred, so load spreads evenly and a failed server\'s keys scatter across many others.','The lookup is a binary search over sorted seat positions, so log of the number of seats.','Replication: store a key on the first R distinct servers clockwise.'],title='Jargon',items=['virtual nodes (vnodes) → even load','lookup = binary search on sorted ring','replicas = next R distinct servers','weights = more vnodes for bigger servers']),
 S('title',['Remember: a ring, a clockwise walk, virtual nodes for balance, and only one over n of keys move. Open the hash ring component to trace it.'],title='Recap',sub='ring • clockwise • vnodes • ~1/n moves'),
]))
L.append(dict(id='c18-caching',title='Caching: LRU, LFU & TTL',used=['p20-lru-cache','p55-lfu-cache'],scenes=[
 S('title',['This lesson is about caches: keeping hot data close, and deciding what to throw away.'],title='Caching',sub='A small desk next to a big library'),
 S('analogy',['Imagine a small desk next to a huge library.','Books you are using right now sit on the desk, so grabbing them is instant. Fetching from the library takes minutes.','The desk only holds five books. When a sixth arrives, one has to go back.','The eviction policy is the rule for which book goes back.'],text='A small fast desk beside a huge slow library. When the desk is full, the eviction policy decides which book goes back.',icons=['hit','miss','evict','policy']),
 S('list',['LRU means least recently used. Throw out the book you have not touched for the longest.','Keep a doubly linked list in use order, plus a hash map from key to node.','On every access, unlink the node and move it to the front. Both steps are constant time.','When full, evict from the back.'],title='LRU = hash map + linked list',states=[dict(nodes=['C','B','A'],labels={'MRU':0,'LRU':2},note='front = most recent'),dict(nodes=['A','C','B'],labels={'MRU':0,'LRU':2},hl=[0],note='get(A) → move to front'),dict(nodes=['D','A','C'],labels={'MRU':0,'LRU':2},hl=[0],note='put(D) when full → evict B')]),
 S('bullets',['LFU means least frequently used. Throw out the book you used the fewest times.','The constant time version keeps one list per use count, plus the current minimum count.','A get moves a key from the count k list to the count k plus one list.','LFU protects popular items from a one time scan, which would flush an LRU cache.'],title='LFU in O(1)',items=['freq → list of keys (LRU within a freq)','track minFreq','get: move key from list k to k+1','resists scans; slow to adapt']),
 S('bullets',['More words you will hear.','Hit rate is the fraction of lookups served from the cache.','TTL, time to live, expires an entry after a fixed time, so stale data cannot live forever.','Write through updates the cache and database together. Write back updates the cache first and flushes later: faster, but you can lose data in a crash.','Cache aside means the application checks the cache, and on a miss, loads from the database and fills the cache.'],title='Jargon',items=['hit rate = hits / lookups','TTL = expire after time','write-through vs write-back','cache-aside (lazy loading)']),
 S('bullets',['Systems examples.','CPU caches use pseudo LRU in hardware because true LRU is too expensive per set.','A CI build cache keys outputs by a hash of the inputs, so a hit is always correct.','And watch for the stampede: when a hot key expires, thousands of requests miss at once. Fix it with a lock per key or early random refresh.'],title='In systems',items=['CPU: pseudo-LRU per set','CI cache: content-addressed keys','Stampede: per-key lock / early refresh','KV-cache blocks for LLM serving']),
 S('title',['A cache is a fast desk with an eviction rule. Practice LRU Cache, then LFU Cache.'],title='Recap',sub='LRU • LFU • TTL • write-through/back'),
]))
L.append(dict(id='c19-queues-backpressure',title='Queues, Backpressure & Lock-Free SPSC',used=['p21-ring-buffer','p59-spsc-queue','p64-bounded-blocking-queue'],scenes=[
 S('title',['This lesson covers queues between threads, what happens when the consumer is slower than the producer, and the lock free single producer, single consumer ring.'],title='Queues & Backpressure',sub='A conveyor belt between two workers'),
 S('analogy',['Picture a conveyor belt between a baker and a packer.','The baker puts loaves on the belt; the packer takes them off.','If the packer is slow, the belt fills up. Now the baker must wait, or loaves fall on the floor.','Telling the baker to slow down is called backpressure.'],text='A conveyor belt between a baker (producer) and a packer (consumer). A full belt must push back on the baker, or loaves are dropped.',icons=['producer','buffer','consumer','backpressure']),
 S('ring',['The single producer, single consumer queue is a ring buffer with two counters.','The producer only writes the tail. The consumer only writes the head. Nobody shares a write, so no lock is needed.','The queue is empty when head equals tail, and full when tail minus head equals the capacity.','Atomics with release and acquire ordering make sure the data is visible before the counter moves.'],title='SPSC ring: head and tail',states=[dict(points=[['head',0,'#34d399'],['tail',0,'#fbbf24']],side={'size':'0'},note='empty: head == tail'),dict(points=[['head',0,'#34d399'],['tail',135,'#fbbf24']],keys=[['x',45],['y',90]],side={'size':'2'},note='producer: write slot, then tail.store(release)'),dict(points=[['head',45,'#34d399'],['tail',135,'#fbbf24']],keys=[['y',90]],side={'size':'1'},note='consumer: head.load / tail.load(acquire)')]),
 S('bullets',['Words to know.','Release ordering on a store says: every write before me is visible to anyone who acquires this value.','Acquire ordering on a load says: I see everything the releasing thread wrote before.','False sharing happens when head and tail sit on the same cache line, so two cores fight over it. Pad them onto separate sixty four byte lines.','Thread sanitizer, or TSan, is a tool that detects data races at run time. Our SPSC tests run clean under it.'],title='Jargon',items=['release store / acquire load','false sharing → align to 64 bytes','TSan = race detector','power-of-two capacity → mask, not modulo']),
 S('bullets',['With several producers or consumers, use a bounded blocking queue: a mutex plus two condition variables, not full and not empty.','Always wait in a while loop, because wakeups can be spurious.','The choices under overload are: block the producer, drop new items, drop old items, or fail fast with an error.','Checkpoint writers in training jobs use exactly this, so a slow disk does not stall the GPUs forever.'],title='Bounded queues & overload',items=['mutex + cv notFull + cv notEmpty','while (!cond) wait — never if','block • drop-new • drop-old • reject','unbounded queues hide overload → OOM']),
 S('title',['Bounded queues and backpressure keep systems alive under load. Try the SPSC queue and the bounded blocking queue problems.'],title='Recap',sub='ring • release/acquire • padding • backpressure'),
]))
L.append(dict(id='c20-replication',title='Replication & Consensus Basics',used=['d02-hash-ring','p27-merge-k-lists'],scenes=[
 S('title',['This lesson covers replication: keeping copies of data on several machines so a failure does not lose anything.'],title='Replication',sub='Photocopies of the class notes'),
 S('analogy',['Imagine one student takes the class notes, and two friends keep photocopies.','If the note taker is sick, a friend can share the notes.','But if the friends copy only once a week, their copies may be out of date.','The big question in replication is: when do we tell the teacher the notes are saved? After one copy, or after all of them?'],text='One note-taker (leader) and friends with photocopies (followers). The question: is a write "done" after one copy, or after several?',icons=['leader','followers','lag','ack']),
 S('flow',['Here is leader based replication.','A client sends a write to the leader.','The leader appends it to its log and sends it to the followers.','Once enough followers confirm, the leader replies OK to the client.'],title='Leader → followers',nodes=[['client',110,200],['leader',330,200],['follower 1',580,120],['follower 2',580,280]],edges=[[0,1],[1,2],[1,3]],states=[dict(hl=[0],dot=[0,1],note='write x = 5'),dict(hl=[1],dot=[1,2],note='append to log, replicate'),dict(hl=[2,3],dot=[1,3],note='followers ack'),dict(hl=[0],note='majority acked → OK to client')]),
 S('bullets',['Vocabulary.','Synchronous replication waits for followers before replying: safe, but slower.','Asynchronous replication replies immediately: fast, but a crash can lose the latest writes.','Replication lag is how far behind a follower is. Reading from a lagging follower can show you old data.','Failover is promoting a follower to leader when the leader dies.'],title='Jargon',items=['sync = safe, slower','async = fast, may lose recent writes','replication lag → stale reads','failover = promote a follower']),
 S('bullets',['Consensus is how replicas agree on one leader and one log order, even when machines crash.','Raft does this with terms, which are numbered election rounds, and a majority vote.','A write is committed once a majority of nodes has it in their log. With five nodes, two can fail and the system still works.','Split brain, two leaders at once, is prevented because two majorities always overlap.'],title='Consensus in one minute (Raft)',items=['term = election round number','leader needs majority votes','commit = on a majority of logs','5 nodes tolerate 2 failures']),
 S('title',['Copies protect data; acks decide safety versus speed; majorities prevent split brain. See the object store and Kafka log designs.'],title='Recap',sub='leader/follower • sync vs async • majority commit'),
]))
L.append(dict(id='c21-sharding',title='Sharding & Partitioning',used=['d02-hash-ring','p27-merge-k-lists','p49-k-closest'],scenes=[
 S('title',['This lesson covers sharding: splitting data across many machines when one machine is not enough.'],title='Sharding',sub='Splitting the phone book'),
 S('analogy',['Imagine a phone book too big for one shelf.','You split it into volumes: A to F on shelf one, G to M on shelf two, and so on.','To find a name, you first pick the right shelf, then search only that volume.','Each shelf is a shard. The rule that picks the shelf is the partition key.'],text='A huge phone book split into volumes on different shelves. The partition key decides which shelf holds a name.',icons=['shard','partition key','router']),
 S('bullets',['Two main ways to split.','Range partitioning keeps keys in sorted ranges, like A to F. Range scans are easy, but a popular range becomes a hot spot.','Hash partitioning spreads keys by hash. Load is even, but range scans must ask every shard.','Many systems combine both: hash on user id, then sort by time inside each shard.'],title='Range vs hash',items=['range: easy scans, hot-spot risk','hash: even load, scatter-gather scans','compound: hash(user) + sort(time)','consistent hashing for rebalancing']),
 S('array',['Here is a hot spot.','Shards are split by hash, but one celebrity user gets most of the traffic.','Shard two is overloaded while the others are idle.','A fix is to split that one hot key across sub keys, like user id plus a random suffix, and merge on read.'],title='Hot spots',states=[dict(a=[25,25,25,25],note='even load per shard (%)'),dict(a=[10,10,70,10],hl=[2],note='celebrity key → shard 2 at 70%'),dict(a=[25,25,25,25],ok=[0,1,2,3],note='salt the hot key across shards')]),
 S('bullets',['Vocabulary.','Rebalancing moves shards when nodes are added. Using many more shards than nodes, like a thousand shards on ten machines, makes moves small.','A router, or coordinator, knows which shard lives where.','A cross shard query is called scatter gather: send to all, then merge the answers, often with a heap for top k.','Cross shard transactions are expensive, so choose a partition key that keeps related data together.'],title='Jargon',items=['rebalancing: many small shards','router / shard map','scatter-gather + merge (heap)','pick a key that co-locates data']),
 S('title',['Pick a partition key, watch for hot spots, and plan rebalancing early. See the vector search and object store designs.'],title='Recap',sub='range vs hash • hot spots • scatter-gather'),
]))
L.append(dict(id='c22-cap-quorums',title='CAP, Consistency & Quorums',used=['d02-hash-ring'],scenes=[
 S('title',['This lesson covers the CAP theorem, consistency levels, and quorums: the vocabulary behind every distributed storage interview question.'],title='CAP & Quorums',sub='Two bank branches, one cut phone line'),
 S('analogy',['Picture two bank branches that share account balances over a phone line.','One day the line is cut. A customer at branch one wants to withdraw money.','Branch one can refuse until the line is back, which is consistent but not available.','Or it can allow it and risk the other branch allowing it too, which is available but not consistent.'],text='Two branches, one cut phone line. Refuse withdrawals (consistent) or allow them and risk double-spending (available). You must pick during the cut.',icons=['C','A','P = the cut line']),
 S('bullets',['CAP stands for consistency, availability and partition tolerance.','Consistency here means every read sees the latest write, as if there were one copy.','Availability means every request to a working node gets an answer.','A partition is a network split. Partitions will happen, so the real choice during one is consistency or availability.'],title='CAP in plain words',items=['C: reads see the latest write','A: every live node answers','P: network splits happen','During P: choose C or A']),
 S('grid',['Quorums make the trade off adjustable.','With N copies, a write waits for W acks, and a read asks R replicas.','If R plus W is greater than N, every read set overlaps every write set, so a read always reaches at least one fresh copy.','With N equals three, W equals two and R equals two, you can lose one node and still read your writes.'],title='Quorum overlap (N = 3)',colLabels=['node1','node2','node3'],rowLabels=['W','R'],states=[dict(g=[['✓','✓','·'],['·','·','·']],hl=[[0,0],[0,1]],note='write acked by W = 2'),dict(g=[['✓','✓','·'],['·','✓','✓']],hl=[[1,1],[1,2]],note='read from R = 2'),dict(g=[['✓','✓','·'],['·','✓','✓']],ok=[[0,1],[1,1]],note='R + W > N → overlap on node2')]),
 S('bullets',['Consistency levels from strongest to weakest.','Linearizable: behaves like one copy with one clock.','Read your writes: you always see your own updates.','Eventual: replicas converge if writes stop, but reads can be stale for a while.','PACELC adds: even without a partition, you trade latency for consistency.'],title='Consistency levels',items=['linearizable (strongest)','read-your-writes / monotonic reads','eventual (weakest)','PACELC: else latency vs consistency']),
 S('title',['During a partition, pick consistency or availability; quorums with R plus W greater than N give overlap. Use this language in every storage design.'],title='Recap',sub='CAP • R + W > N • consistency levels'),
]))
